// Define UI components (reusable)
async function createBaseScreen(name) {
    const frame = figma.createFrame();
    frame.name = name;
    frame.resize(375, 812);
    frame.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
    return frame;
}

